"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3387],{1269(a){a.exports=JSON.parse('{"title":"\uc6f9\ubdf0\uc758 \ud568\uc815","date":"2024-08-02","coverUrl":null,"html":"<h2 data-notion-block-id=\\"039a247e-477a-4d5b-82fe-fff52668ae1c\\" id=\\"039a247e-477a-4d5b-82fe-fff52668ae1c\\">\uc6f9\ubdf0\uc758 \ud568\uc815</h2><a href=\\"https://frontendmasters.com/blog/the-pitfalls-of-in-app-browsers/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/the-pitfalls-of-in-app-browsers/</a><p data-notion-block-id=\\"68a77a94-7917-4406-80c2-c65984af6f09\\"><b>\uc2ec\uc724\uc12d</b>: \ucd5c\uadfc \uce74\uce74\uc624\ud1a1\uc5d0 \uc788\uc5c8\ub358 MITM\uacf5\uaca9(<a href=\\"https://stulle123.github.io/posts/kakaotalk/secret-chat/\\">\uce74\uce74\uc624\ud1a1 E2EE \ubc84\uadf8 \ubc14\uc6b4\ud2f0</a>)\ub610\ud55c \uadf8\ub807\uace0, \uc778\uc571\ube0c\ub77c\uc6b0\uc800\ub294 \ubcf4\uc548, \uc131\ub2a5, \ud638\ud658\uc131 \uc774\uc288\ub97c \ud3ec\ud568\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub9ce\uc774 \uc0ac\uc6a9\ud558\uc2dc\ub294 \uc774\uc720\ub294 \uc548\ub0b4 \ud398\uc774\uc9c0\ub97c \ub9cc\ub4e4\uae30 \ud798\ub4e4\uc5b4\uc11c\uac00 \uc544\ub2d0\uc9c0 \uc0dd\uac01\ud569\ub2c8\ub2e4. Inject\ub97c \ud0d0\uc9c0\ud574\uc11c \uc548\ub0b4\ub97c \ud574\uc8fc\uac70\ub098, URI hack\uc744 \ud1b5\ud574\uc11c\ubc16\uc5d0 \ube60\uc838\ub098\uac08 \uc218 \uc788\uc9c0\ub9cc, \uc778\uc571 \ube0c\ub77c\uc6b0\uc800\uac00 \uc904\uc5b4\ub4dc\ub294 \ub0a0\uc774 \uc654\uc73c\uba74 \uc88b\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"e974e7a8-9bb8-45cd-afc3-502c83efca65\\" id=\\"e974e7a8-9bb8-45cd-afc3-502c83efca65\\">\uc11c\ubc84 \ub80c\ub354\ub9c1 \ubc29\uc2dd \uc124\uba85\ud68c</h2><a href=\\"https://vercel.com/blog/how-to-choose-the-best-rendering-strategy-for-your-app\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/how-to-choose-the-best-rendering-strategy-for-your-app</a><p data-notion-block-id=\\"a6bb8fc9-fdf1-42d2-a3de-7586563bc4da\\"><b>\uc2ec\uc724\uc12d</b>: Vercel\uc5d0\uc11c NextJS\uc5d0 App router\uc744 \ub9cc\ub4e4\uba74\uc11c \uac1c\ub150\uc740 \uc57d\ud574\uc84c\uc9c0\ub9cc \uc544\uc9c1 React\uc5d0\uc11c(React \uc678\uc758 \ud504\ub860\ud2b8\uc5d4\ub4dc\uc5d0\uc11c\ub3c4) \ub9ce\uc740 \ubd80\ubd84\uc5d0\uc11c \uc0ac\uc6a9\ub418\uace0 \uc788\ub294 SSR, SSG, ISR \uac1c\ub150\uacfc \uc774\uc804\uc5d0 \uc124\uba85\ud588\ub358 \ubd80\ubd84 \ubbf8\ub9ac \ub80c\ub354\ub9c1(<a href=\\"https://ones-to-watch.ethansup.net/news/post/a5902c7d-ee33-4db6-aaea-ea4820a7562f#40711796-00d7-43e8-b52a-1f0b0f9d4cae\\">PPR</a>)\uc5d0 \ub300\ud574 \uc124\uba85\ud569\ub2c8\ub2e4. NextJS\uc5d0 \uc5f0\uacb0\uc9c0\uc740 \uac1c\ub150\uc774\uc9c0\ub9cc, \uc774\ud574\ud558\uae30 \uc27d\uac8c \ud574\uc8fc\uae30 \ub54c\ubb38\uc5d0 \ud55c \ubc88\ucbe4 \ubcf4\uc168\uc73c\uba74 \uc88b\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"3e140bfa-3a2c-4b96-8deb-3d71737123b8\\" id=\\"3e140bfa-3a2c-4b96-8deb-3d71737123b8\\">\ud14d\uc2a4\ud2b8 \uac00\ub3c5\uc131</h2><a href=\\"https://baymard.com/blog/line-length-readability\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://baymard.com/blog/line-length-readability</a><p data-notion-block-id=\\"4d3ef95c-3483-485e-a11c-124a0971e4a0\\"><b>\uc2ec\uc724\uc12d</b>: line-height\uacfc \ud589\ub2f9 \uae00\uc790 \uac1c\uc218\uc5d0 \ub530\ub978 \uac00\ub3c5\uc131 \ubb38\uc81c\ub97c \ub2e4\ub8ec \uae00\uc785\ub2c8\ub2e4. \uae30\ub2a5\uc744 \ub9cc\ub4e4 \ub54c\ub294 \ub193\uce58\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc9c0\ub9cc, \ud6c4\uc5d0 \uc2dc\uac04\uc774 \ub0a0 \ub54c \uc81c\uc548\ud558\uac70\ub098 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c(\ub098 \uac00\uc774\ub4dc)\uc5d0 \ub123\uc73c\uba74 \uc88b\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"453e4eb2-6669-47de-99db-b45d1cb87561\\" id=\\"453e4eb2-6669-47de-99db-b45d1cb87561\\">???: third-party \ucfe0\ud0a4 \uc5c6\uc568\uac81\ub2c8\ub2e4</h2><a href=\\"https://privacysandbox.com/news/privacy-sandbox-update/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://privacysandbox.com/news/privacy-sandbox-update/</a><p data-notion-block-id=\\"aa968806-3832-44b6-bfa8-05da4b3a5544\\"><b>\uc2ec\uc724\uc12d</b>: third-party \ucfe0\ud0a4\ub97c \uc5c6\uc560\uace0 Privacy Sandbox API\ub85c \uc804\ud658\ud558\uaca0\ub2e4\ub294 \uad6c\uae00\uc758 \uc5c4\ud3ec\uc640 \ud568\uaed8 \uc5ec\ub7ec \ud68c\uc0ac\uc5d0\uc11c GA4\uc5d0\uc11c \uad50\uccb4\ud558\uac70\ub098 \ub2e4\ub978 \ubc29\ubc95\uc744 \ucc3e\uc73c\ub824\ub294 \uc2dc\ub3c4\ub4e4\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4(<a href=\\"https://ones-to-watch.ethansup.net/news/post/6631ddbe-1279-426c-88c7-e9e02785bbb6#59b92163-82ad-475b-9b80-f9c8f5ce6309\\">Sentry\uc5d0\uc11c \ubaa8\ub4e0 \uad11\uace0 \ucfe0\ud0a4 \uc81c\uac70 \uc0ac\ub840</a>). \uc0c8\ub85c\uc6b4 \uc811\uadfc \ubc29\uc2dd\uc744 \uc81c\uacf5\ud55c\ub2e4\uace0 \ubc1d\ud614\ub294\ub370, \uc0c1\uc6a9\ud654\ub418\uae30\uc5d4 \uba40\uc5c8\uc744 \uc218\ub3c4 \uc788\ub2e4\uace0 \uc0dd\uac01\ub418\ub124\uc694. \uc774\ubbf8 <a href=\\"https://privacysandbox.com/news/update-on-the-plan-for-phase-out-of-third-party-cookies-on-chrome/\\">\uc11c\ub4dc\ud30c\ud2f0 \ucfe0\ud0a4 \uc9c0\uc6d0 \uc911\ub2e8\uc744 \ubbf8\ub8e8\uae30</a>\ub3c4 \ud588\uad6c\uc694. W3C\uc5d0\uc11c\ub294 <a href=\\"https://www.w3.org/blog/2024/third-party-cookies-have-got-to-go/\\">\ube60\ub974\uac8c \ud0c0\uc0ac \ucfe0\ud0a4\ub97c \uc5c6\uc560\uc57c \ud55c\ub2e4</a>\ub294 \uae00\uc744 \ubc1c\ud589\ud558\uae30\ub294 \ud588\ub294\ub370, \uc5b4\ub5bb\uac8c \ub420\uc9c0\ub294 \uc9c0\ucf1c\ubd10\uc57c \ud560 \uac83 \uac19\ub124\uc694.</p><h2 data-notion-block-id=\\"7ee25949-e63f-4e76-aa16-0385dd6b0286\\" id=\\"7ee25949-e63f-4e76-aa16-0385dd6b0286\\">State of React 2023</h2><a href=\\"https://2023.stateofreact.com/en-US/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://2023.stateofreact.com/en-US/</a><p data-notion-block-id=\\"67812d14-98b8-439f-9d72-b58e5bdc67e4\\">\uac04\ub2e8\ud558\uac8c React\uc758 \ud2b8\ub80c\ub4dc\ub97c \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \uc124\ubb38\uc870\uc0ac \uacb0\uacfc\uc785\ub2c8\ub2e4. \uac00\ubccd\uac8c \ubcf4\uace0 \ub118\uc5b4\uac00\ub3c4 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"6d39613c-609f-4fa4-936d-815f8ca62027\\" id=\\"6d39613c-609f-4fa4-936d-815f8ca62027\\"><code>box-shadow</code> \uc5c6\uc774 \uadf8\ub9bc\uc790 \ud45c\ud604\ud558\uae30</h2><a href=\\"https://dgerrells.com/blog/how-not-to-use-box-shadows\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dgerrells.com/blog/how-not-to-use-box-shadows</a><p data-notion-block-id=\\"2f6ce2fd-6f6f-40ff-9686-0d35236f812f\\">JS\ub85c \uc560\ub2c8\uba54\uc774\uc158\uacfc \ub808\uc774 \uce90\uc2a4\ud305\uc744 \uad6c\ud604\ud558\ub294 \uc7ac\ubc0c\ub294 \uae00\uc785\ub2c8\ub2e4. \uc77c\ubc18\uc801\uc778 \uae00\uc740 \uc544\ub2c8\ub2c8 \ud765\ubbf8\ub85c\uc6b4 \ubd84\ub9cc \ubcf4\uc138\uc694. \uc27d\uac8c \uc811\uadfc\ud560 \uc218 \uc788\ub294 \uae00\uc740 <a href=\\"https://tech.kakaopay.com/post/dion-interactive-animation/\\">\uce74\uce74\uc624\ud398\uc774 \ud300\uc758 API\uc5c6\uc774 \uc6f9 \uc560\ub2c8\uba54\uc774\uc158 \uad6c\ud604 \uc2dc\ub9ac\uc988</a>\uac00 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"c4b7cc50-fe2d-4623-9b6d-b7cbe57aec8e\\" id=\\"c4b7cc50-fe2d-4623-9b6d-b7cbe57aec8e\\">Native\uc5d0\uc11c React Native \uc804\ud658\uc758 \uad50\ud6c8</h2><a href=\\"https://stepchange.work/blog/migrating-coinbases-56-million-users-to-react-native-key-lessons-and-takeaways\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://stepchange.work/blog/migrating-coinbases-56-million-users-to-react-native-key-lessons-and-takeaways</a><p data-notion-block-id=\\"d861b08c-c24d-46af-ad21-5a6200397401\\">RN\uc744 \uc801\uc6a9\ud558\uac8c \ub41c \uc774\uc720\uc640 \uc7a5\uc810(\ube60\ub978 \uac1c\ubc1c, OTA \uc5c5\ub370\uc774\ud2b8), \ub2e8\uc810(\ubcf5\uc7a1\ud55c \ub370\uc774\ud130\ub97c \ub2e4\ub8f0 \ub54c\uc758 \uc131\ub2a5 \uc800\ud558, \ub124\ube44\uac8c\uc774\uc158 \ubcf5\uc7a1\uc131)\uc744 \uc18c\uac1c\ud558\uace0 RN\uc744 \uc801\uc6a9\ud558\ub824\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc870\uc5b8\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"461afe37-5f65-4800-978a-8227e6534566\\" id=\\"461afe37-5f65-4800-978a-8227e6534566\\">DRY\uac00 \uc798\ubabb\ub418\uc5b4\uac00\ub294 \ubc29\uc2dd</h2><a href=\\"https://swizec.com/blog/dry-the-common-source-of-bad-abstractions/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://swizec.com/blog/dry-the-common-source-of-bad-abstractions/</a><p data-notion-block-id=\\"5b021c89-48c8-4e1c-941b-73933f711765\\">\ucd94\uc0c1\ud654\ub294 \ub9e4\uc6b0 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \\"\ub2e4\ub978 \ud568\uc218 \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc774 \uc0ac\uc6a9\ud558\ub3c4\ub85d \ucd94\uc0c1\ud654\ud558\uae30\\". \ub4e3\uae30\ub9cc \ud574\ub3c4 \ucef4\ud4e8\ud130 \ub044\uace0 \uc2f6\uc740 \uc870\ud569\uc774\ub124\uc694. \uc88b\uc740 \ucf54\ub4dc\ubca0\uc774\uc2a4\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#ec85017c-c8bc-46e1-abbe-e69801686efa\\">\uc801\ub2f9\ud788 \ucd94\uc0c1\ud654\ud558\ub294 \uac83</a>\uc774\uc9c0\ub9cc(\ud56d\uc0c1 \uace0\ubbfc\uc774 \ub418\ub294 \ud568\uc218\ub098 \ucef4\ud3ec\ub10c\ud2b8\ub97c \uc5b4\ub5bb\uac8c \ubd84\ub9ac\ud560\uae4c\ub3c4 \ube44\uc2b7\ud55c \uace0\ubbfc\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.) \ub9d0\ub9cc \uc27d\uc2b5\ub2c8\ub2e4. \uc88b\uc740 \ubc29\uc2dd\uc740 \ub9ce\uc774 \uc4f0\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 \uc5b4\ub5bb\uac8c \ucd94\uc0c1\ud654\ud588\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uacf5\ubd80\ud558\ub294 \uc218 \ubc16\uc5d0 \uc5c6\uaca0\uc8e0. \uc774 \uae00\uc740 \uac04\ub2e8\ud55c \uc0c1\ud669\uc744 \uac00\uc815\ud558\uace0 \uc5b4\ub5bb\uac8c \ucd94\uc0c1\ud654\uac00 \uc798\ubabb\ub418\uc5b4\uac00\ub294\uc9c0 \uc124\uba85\ud569\ub2c8\ub2e4. \ud754\ud788 \ub9ce\uc774 \ud558\ub294 \uc2e4\uc218\ub77c\uace0 \uc0dd\uac01\ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p>"}')}}]);